with filtered_web_events as (select * from web_events where not (session_id in (18, 23, 28) or duration_sec between 190 and 373)), summary as (select hour(event_time) as event_hour, year(event_time) as event_year, sum(duration_sec) as total_duration_sec from filtered_web_events group by hour(event_time), year(event_time)) select event_hour, total_duration_sec from summary order by event_hour desc, total_duration_sec;
